import{_ as r,o as t,c as a,a2 as n}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Mehrsprachige Formulare","description":"Formulartexte in mehreren Sprachen pflegen.","frontmatter":{"title":"Mehrsprachige Formulare","description":"Formulartexte in mehreren Sprachen pflegen."},"headers":[],"relativePath":"formulare/mehrsprachig.md","filePath":"formulare/mehrsprachig.md","lastUpdated":1786092153000}'),i={name:"formulare/mehrsprachig.md"};function s(l,e,d,h,o,c){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="mehrsprachige-formulare" tabindex="-1">Mehrsprachige Formulare <a class="header-anchor" href="#mehrsprachige-formulare" aria-label="Permalink to &quot;Mehrsprachige Formulare&quot;">​</a></h1><p>Ein Formular kann seine Texte in mehreren Sprachen führen. Ausfüllende sehen es in ihrer Sprache.</p><p>Die Beschreibung in der Oberfläche: <em>Aktivieren Sie diese Funktion, um mehrere Sprachen für Ihr Formular zu unterstützen.</em></p><div class="warning custom-block"><p class="custom-block-title">Nur im höchsten Tarif</p><p>Mehrsprachigkeit steht nur im Pro-Tarif zur Verfügung.</p></div><h2 id="einschalten" tabindex="-1">Einschalten <a class="header-anchor" href="#einschalten" aria-label="Permalink to &quot;Einschalten&quot;">​</a></h2><p>Im Reiter <strong>Mehr</strong>: <strong>Mehrere Sprachen</strong>. Danach führt <strong>Übersetzungen bearbeiten</strong> zum <strong>Formular-Spracheditor</strong>.</p><h2 id="standardsprache" tabindex="-1">Standardsprache <a class="header-anchor" href="#standardsprache" aria-label="Permalink to &quot;Standardsprache&quot;">​</a></h2><p>Die <strong>Standardsprache</strong> ist die Sprache der Texte, die Sie im Formular-Builder eingetragen haben.</p><blockquote><p><em>Dies ist die Sprache, die den im Formular-Builder bereits eingerichteten Texten entspricht.</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Standardsprache nicht im Spracheditor bearbeiten</p><p>Die Texte der Standardsprache ändern Sie im normalen Formular-Editor, nicht im Spracheditor. Legen Sie das Formular also zuerst vollständig in einer Sprache an und übersetzen Sie danach.</p></div><h2 id="weitere-sprachen-hinzufugen" tabindex="-1">Weitere Sprachen hinzufügen <a class="header-anchor" href="#weitere-sprachen-hinzufugen" aria-label="Permalink to &quot;Weitere Sprachen hinzufügen&quot;">​</a></h2><p>Unter <strong>Zusätzliche Sprachen</strong> fügen Sie beliebig viele Sprachen hinzu:</p><blockquote><p><em>Sie können hier eine oder mehrere zusätzliche Sprachen hinzufügen.</em></p></blockquote><p>Die Auswahl umfasst über 180 Sprachen, jeweils mit ihrem eigensprachlichen Namen.</p><p>Über <strong>Aktuelle Sprache</strong> wechseln Sie zwischen den Sprachen, die Sie gerade bearbeiten.</p><h2 id="was-ubersetzt-wird" tabindex="-1">Was übersetzt wird <a class="header-anchor" href="#was-ubersetzt-wird" aria-label="Permalink to &quot;Was übersetzt wird&quot;">​</a></h2><h3 id="globale-formulartexte" tabindex="-1">Globale Formulartexte <a class="header-anchor" href="#globale-formulartexte" aria-label="Permalink to &quot;Globale Formulartexte&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feld</th><th>Entspricht</th></tr></thead><tbody><tr><td><strong>Formular Titel</strong></td><td>Titel des Formulars</td></tr><tr><td><strong>Formular Beschreibung</strong></td><td>Beschreibung</td></tr><tr><td><strong>Absenden Button</strong></td><td>Beschriftung des Absende-Buttons</td></tr><tr><td><strong>Überschrift Erfolgsseite</strong></td><td>Titel der <a href="/docs/formulare/erfolgsseite">Erfolgsseite</a></td></tr><tr><td><strong>Nachricht Erfolgsseite</strong></td><td>Nachricht der Erfolgsseite</td></tr><tr><td><strong>Button Erfolgsseite</strong></td><td>Button-Text auf der Erfolgsseite</td></tr></tbody></table><h3 id="formular-felder" tabindex="-1">Formular Felder <a class="header-anchor" href="#formular-felder" aria-label="Permalink to &quot;Formular Felder&quot;">​</a></h3><p>Beschriftungen und Beschreibungen aller Felder.</p><h3 id="textblocke" tabindex="-1">Textblöcke <a class="header-anchor" href="#textblocke" aria-label="Permalink to &quot;Textblöcke&quot;">​</a></h3><p>Alle eingefügten Text- und Überschriftenblöcke.</p><h2 id="was-nicht-ubersetzt-wird" tabindex="-1">Was nicht übersetzt wird <a class="header-anchor" href="#was-nicht-ubersetzt-wird" aria-label="Permalink to &quot;Was nicht übersetzt wird&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Daten bleiben, wie sie sind</p><p>Übersetzt werden nur die <strong>Texte des Formulars</strong> — nicht die Inhalte:</p><ul><li><strong>Auswahloptionen</strong> einer Einzel- oder Mehrfachauswahl bleiben in der Sprache, in der sie im Grid stehen</li><li><strong>Verknüpfte Einträge</strong> erscheinen mit ihrem Wert aus dem Zielgrid</li><li><strong>Fehlermeldungen</strong> und Systemtexte folgen der Spracheinstellung der Anwendung</li></ul><p>Für mehrsprachige Auswahloptionen gibt es keine Lösung im Formular. Bei zwei Sprachen ist manchmal eine zweisprachige Option der pragmatische Weg — etwa <code>Rechnung / Invoice</code>.</p></div><h2 id="vorgehen-in-der-praxis" tabindex="-1">Vorgehen in der Praxis <a class="header-anchor" href="#vorgehen-in-der-praxis" aria-label="Permalink to &quot;Vorgehen in der Praxis&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Erst fertigstellen, dann übersetzen</p><p>Jede spätere Änderung an einem Feldlabel oder Textblock muss in <strong>allen</strong> Sprachen nachgezogen werden. Legen Sie das Formular deshalb zuerst inhaltlich fest und übersetzen Sie es zum Schluss.</p><p>Bei laufenden Änderungen lohnt sich eine Liste, welche Texte in welcher Sprache aktuell sind — der Spracheditor zeigt nicht an, was seit der Übersetzung geändert wurde.</p></div><div class="tip custom-block"><p class="custom-block-title">Mit einer zweiten Sprache anfangen</p><p>Zwei Sprachen sind übersichtlich zu pflegen. Ab drei bis vier wird jede Formularänderung aufwendig. Prüfen Sie, ob wirklich alle Sprachen gebraucht werden — oder ob je Sprache ein eigenes Formular praktikabler ist.</p></div><h2 id="alternative-mehrere-formulare" tabindex="-1">Alternative: mehrere Formulare <a class="header-anchor" href="#alternative-mehrere-formulare" aria-label="Permalink to &quot;Alternative: mehrere Formulare&quot;">​</a></h2><p>Statt eines mehrsprachigen Formulars können Sie <strong>je Sprache ein eigenes Formular</strong> auf dasselbe Grid anlegen und den passenden Link verteilen.</p><table tabindex="0"><thead><tr><th></th><th>Ein mehrsprachiges Formular</th><th>Mehrere Formulare</th></tr></thead><tbody><tr><td>Tarif</td><td>nur Pro</td><td>jeder Tarif</td></tr><tr><td>Pflegeaufwand</td><td>ein Formular, mehrere Textsätze</td><td>je Sprache alles doppelt</td></tr><tr><td>Struktur ändern</td><td>einmal</td><td>in jedem Formular</td></tr><tr><td>Links</td><td>ein Link</td><td>ein Link je Sprache</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Wann mehrere Formulare besser sind</p><p>Wenn sich die Formulare je Sprache ohnehin unterscheiden sollen — etwa andere Pflichtfelder je Land — sind getrennte Formulare die klarere Lösung. Sie sind zudem nicht tarifgebunden.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/formulare/formular-erstellen">Formular erstellen</a></li><li><a href="/docs/formulare/erfolgsseite">Erfolgsseite und Weiterleitung</a></li><li><a href="/docs/formulare/formular-teilen">Formular teilen</a></li></ul>',33)])])}const p=r(i,[["render",s]]);export{m as __pageData,p as default};
